const stockCheckRequestViewModel = ({
    parent
} = {
    parent: {}
    }) => { 

    //#region Properties

    let self = {
        parent: parent
    }

    self.validateNow = ko.observable(false);

    self.busy = ko.observable(false);

    self.modalElement = document.querySelector('#stock-check-request-modal');

    self.modal = $(self.modalElement).modal;

    self.quantity = {
        label: 'Quantity',
        observable: ko.observable().extend({
            required: {
                params: true,
                onlyIf: function () {
                    return self.validateNow()
                },
                message: ' '
            },
            numberFormatted: {
                digits: 0,
                currency: {
                    FormattingCulture: 'en-GB'
                }
            },
            min: {
                params: 1,
                onlyIf: function () {
                    return self.validateNow()
                },
                message: 'Minimum 1 Item'
            },
            max: {
                params: 99,
                onlyIf: function () {
                    return self.validateNow()
                },
                message: 'Maximum 99 Items'
            },
            notEqual: {
                params: "",
                onlyIf: function () {
                    return self.validateNow()
                },
                message: 'Quantity == ""'
            },
            //notEqual: {
            //    params: 0,
            //    onlyIf: function () {
            //        return self.validateNow()
            //    },
            //    message: 'Quantity == 0'
            //}
        }),
        useNativeValidation: false,
        decorateInputElement: false,
        insertValidationMessages: false,
        showClear: false
    };

    //#endregion

    //#region Components

    self.errors = ko.validation.group([
        self.productId,
        self.quantity
    ]);

    //#endregion

    //#region Computeds



    //#endregion

    //#region Subscriptions



    //#endregion

    //#region Methods

    self.showModal = () => {
        self.reset();
        self.modal.show();
    }

    self.hideModal = () => {
        self.modal.hide();
    }

    self.submit = () => {

        self.validateNow(true);

        if (self.errors().length) {

            self.errors.showAllMessages(true);

            self.errors.filter(x => {
                x.isValid.notifySubscribers(x.isValid());
            });

        } else {
            $.confirm("Are you sure?", "Please double check the quantity you're requesting.", () => {

                let params = {
                    productId: self.productId(),
                    quantity: self.quantity(),
                    tradeAccountId: self.parent.TradeAccount.TradeAccountID,
                    basketId: self.parent.parent.orderFactory.basketId()
                }

                console.log("InsertStockCheckRequest calling with", params)

                fetch("/api/componentapi/InsertStockCheckRequest", {
                    method: 'POST',
                    headers: window.fetchHeaders,
                    cache: 'no-cache',
                    body: JSON.stringify(params)
                })
                    .then(window.handleFetchResponse)
                    .then(data => {
                        console.log("InsertStockCheckRequest returned", data)
                    })
                    .catch(err => {
                        self.busy(false);
                        window.catchFetchError(err);
                    })
            }, null);
        }
    }

    self.reset = () => {
        self.validateNow(false);
        self.quantity(undefined);
    }

    //#endregion

    //#region Events



    //#endregion

    return self;
}